rules.fix_code:
.grain::after {
  content: ""; position: absolute; inset: 0;
  pointer-events: none; opacity: .05;
  background-image: url("data:image/svg+xml,...feTurbulence type='fractalNoise' baseFrequency='0.7' numOctaves='2' stitchTiles='stitch'...");
  background-repeat: repeat;  /* a 160px tile, NOT a full-viewport filter */
}

figure img {
  display: block; width: 100%; height: auto;
  aspect-ratio: 4 / 3; object-fit: cover;
  border-radius: 12px;
  outline: 1px solid var(--line); outline-offset: -1px;  /* inset hairline */
  filter: saturate(.92);  /* ~8% desaturation to match the ground */
}
